package com.siiiweb.statistics.controller;import org.springframework.data.redis.core.StringRedisTemplate;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController public class StatisticsController{private final StringRedisTemplate redis;public StatisticsController(StringRedisTemplate r){redis=r;}@GetMapping("/api/statistics/overview") public Map<String,Object> overview(){Long visit=redis.opsForValue().increment("site:visit");return Map.of("visits",visit,"articleViews","redis:article:view:*","online","demo");}}
